<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    prokube.ai/sandbox-pool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">default</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # sizes select their pool by this label</span></span>
